@using sv_080bd5f2a8af492b871a869fb440f9a3.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" OnNavigateToStep="NavigateToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@fullName"
                              Email="@email"
                              Phone="@phone"
                              Address="@address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalNext" />
            break;

        case 1:
            <WorkHistoryStep Entries="workEntries"
                             OnNext="HandleWorkNext"
                             OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep References="references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep CoverLetterText="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep Personal="@GetPersonalInfo()"
                        WorkEntries="@GetWorkEntries()"
                        References="@GetReferences()"
                        CoverLetter="@coverLetter"
                        OnEditStep="NavigateToStep"
                        OnBack="GoBack"
                        OnSubmit="HandleSubmit"
                        @ref="reviewStepRef" />
            break;
    }
</div>

@code {
    private int currentStep = 0;
    private ReviewStep? reviewStepRef;

    // Step 1 state
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2 state
    private List<WorkHistoryStep.WorkEntryModel> workEntries = new()
    {
        new WorkHistoryStep.WorkEntryModel()
    };

    // Step 3 state
    private List<ReferencesStep.ReferenceModel> references = new()
    {
        new ReferencesStep.ReferenceModel(),
        new ReferencesStep.ReferenceModel()
    };

    // Step 4 state
    private string coverLetter = "";

    private void NavigateToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0) currentStep--;
    }

    private void HandlePersonalNext((string FullName, string Email, string Phone, string Address) data)
    {
        fullName = data.FullName;
        email = data.Email;
        phone = data.Phone;
        address = data.Address;
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkHistoryStep.WorkEntryModel> entries)
    {
        workEntries = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        var application = new JobApplication(
            GetPersonalInfo(),
            new WorkHistory(GetWorkEntries()),
            GetReferences(),
            coverLetter
        );

        var applicationId = await ApplicationService.SubmitApplicationAsync(application);

        if (reviewStepRef is not null)
        {
            reviewStepRef.IsSubmitted = true;
            reviewStepRef.ApplicationId = applicationId;
        }
    }

    private PersonalInfo GetPersonalInfo() =>
        new(fullName, email, phone, address);

    private List<WorkEntry> GetWorkEntries() =>
        workEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList();

    private List<Reference> GetReferences() =>
        references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
}
